# Nginx redirect map — generated by migration skill 13 (vanity URLs)
# Site: supercar-garage | Source: https://www.ultimate-supercar-garage.com/sitemap.xml
# Usage in nginx.conf:
#   map $request_uri $redirect_uri {
#       include /etc/nginx/redirects.map;
#   }
#   if ($redirect_uri) { return 301 $redirect_uri; }
#
# Format: ~^<regex>$   <target-path-or-url>;
#   - Direct fr-FR paths redirect to the canonical Jahia page slug
#   - EN alias paths redirect to the same page (Jahia serves both fr+en from one node)
#   - Utility pages (search, sitemap, legal) are flagged for manual 410/301 handling

# === Home page ===
~^/fr\-FR$	/;
~^/en$	/;

# === FR-FR pages (direct slug match) ===
~^/fr\-FR/evenement(/.*)?$	/evenement;
~^/fr\-FR/actualites(/.*)?$	/actualites;
